test('first registration starts exactly 30 server-timed days and retry cannot reset it', async () => {
  const response = await call('POST', '/license/register', device);
  assert.equal(response.statusCode, 200, response.body);
  const state = response.json<LicenseState>();
  assert.equal(state.state, 'trial'); assert.equal(state.remainingDays, 30);
  assert.equal(state.requestCode, `GM1-${device.requestId}`);
  assert.equal(state.activationConfigured, true);
  assert.ok(Math.abs(Date.parse(state.trialExpiresAt) - Date.parse(state.serverTime) - 30 * DAY) < 1000);
  const repeated = (await call('POST', '/license/register', device)).json<LicenseState>();
  assert.equal(repeated.trialExpiresAt, state.trialExpiresAt);
  const impersonated = await call('POST', '/license/register', { ...device, secret: randomBytes(32).toString('hex') });
  assert.equal(impersonated.statusCode, 403);
  assert.equal((await call('GET', '/license/status', undefined, { ...device, secret: randomBytes(32).toString('hex') })).statusCode, 403);
  assert.equal((await app.inject({ method: 'GET', url: '/customers' })).statusCode, 400);
  assert.equal((await app.inject({ method: 'GET', url: '/customers', headers: {
    'x-installation-id': device.requestId, 'x-installation-secret': device.secret,
  } })).statusCode, 401);
});

test('trial boundary denies exactly at 30 days independent of any phone clock', () => {
  const expiry = new Date('2026-12-01T00:00:00.000Z');
  const fixture = { request_id: device.requestId, secret_hash: '', trial_expires_at: expiry, license_expires_at: null };
  assert.equal(licenseState({ ...fixture, server_time: new Date(expiry.getTime() - 1) }, true).state, 'trial');
  assert.equal(licenseState({ ...fixture, server_time: expiry }, true).state, 'expired');
  assert.equal(licenseState({ ...fixture, server_time: new Date(expiry.getTime() + DAY) }, true).remainingDays, 0);
});

