test('invalid, tampered, other-phone, expired and future-issued licenses are refused', async () => {
  const now = new Date(), expiry = new Date(now.getTime() + 7 * DAY).toISOString();
  const valid = issueLicense(issuer.privateKey, passphrase, `GM1-${device.requestId}`, expiry, now);
  assert.equal(verifyLicenseToken(valid, device.requestId, now, publicKey).requestId, device.requestId);
  const [prefix, data, signature] = valid.split('.');
  const tampered = `${prefix}.${Buffer.from(JSON.stringify({ version: 1, requestId: device.requestId, issuedAt: now.toISOString(), expiresAt: '2099-01-01T00:00:00.000Z' })).toString('base64url')}.${signature}`;
  const otherPhone = issueLicense(issuer.privateKey, passphrase, `GM1-${randomUUID()}`, expiry, now);
  const pastLicense = issueLicense(issuer.privateKey, passphrase, `GM1-${device.requestId}`, new Date(now.getTime() - DAY).toISOString(), new Date(now.getTime() - 2 * DAY));
  const futureIssued = issueLicense(issuer.privateKey, passphrase, `GM1-${device.requestId}`, expiry, new Date(now.getTime() + DAY));
  for (const key of ['bad', `${prefix}.${data}.AAAA`, tampered, otherPhone, pastLicense, futureIssued]) {
    const result = await call('POST', '/license/activate', { key });
    assert.equal(result.statusCode, 400, result.body);
  }
});

test('valid key restores access, renewal extends it, retries never shorten it, and expiry relocks it', async () => {
  const expiry = new Date(Date.now() + 7 * DAY).toISOString();
  const key = issueLicense(issuer.privateKey, passphrase, `GM1-${device.requestId}`, expiry);
  const activation = await call('POST', '/license/activate', { key });
  assert.equal(activation.statusCode, 200, activation.body);
  assert.equal(activation.json<LicenseState>().state, 'licensed');
  assert.equal((await call('GET', '/customers')).statusCode, 200);
  const renewedExpiry = new Date(Date.now() + 30 * DAY).toISOString();
  const renewed = issueLicense(issuer.privateKey, passphrase, `GM1-${device.requestId}`, renewedExpiry);
  await call('POST', '/license/activate', { key: renewed });
  const retry = await call('POST', '/license/activate', { key });
  assert.equal(retry.json<LicenseState>().licenseExpiresAt, renewedExpiry);
  await pool.query('UPDATE installations SET license_expires_at=$1 WHERE request_id=$2', [new Date(Date.now() - 1000), device.requestId]);
  assert.equal((await call('GET', '/customers')).statusCode, 402);
});

