test('issuer creates encrypted private keys outside source and refuses overwriting, invalid request and short passphrase', async () => {
  const keyDirectory = join(directory, 'issuer');
  const keys = await initializeIssuer(keyDirectory, passphrase);
  try {
    const privatePem = await readFile(keys.privatePath, 'utf8');
    assert.match(privatePem, /ENCRYPTED PRIVATE KEY/);
    await assert.rejects(() => initializeIssuer(keyDirectory, passphrase), /EEXIST/);
    await assert.rejects(() => initializeIssuer(join(directory, 'invalid'), 'short'), /16/);
    await assert.rejects(() => initializeIssuer(join(process.cwd(), '..inside-project'), passphrase), /outside the application/);
    assert.throws(() => issueLicense(privatePem, 'wrong', `GM1-${device.requestId}`, new Date(Date.now() + DAY).toISOString()));
    assert.throws(() => issueLicense(privatePem, passphrase, 'bad-code', new Date(Date.now() + DAY).toISOString()), /request code/);
    assert.throws(() => issueLicense(privatePem, passphrase, `GM1-${device.requestId}`, '2020-01-01T00:00:00Z'), /future/);
    assert.throws(() => issueLicense(privatePem, passphrase, `GM1-${device.requestId}`, '2099-02-30T00:00:00Z'), /real UTC calendar/);
  } finally {
    await unlink(keys.privatePath); await unlink(keys.publicPath); await rmdir(keyDirectory);
  }
});
